import React from 'react';

import A4Page from '@components/A4Page';
import { selectHikerAsync } from '@components/HikerSelector/hikerSelectHelper';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';

import PohodnikCard from './components/PohodnikCard';
import PohodnikChevron from './components/PohodnikChevron';
import logo from '../../img/svg/pohColor.svg';
import { getHikingDataAsync } from '../Hiking/@services/hiking.service';
import { IHikingData } from '../Hiking/@types/hiking.types';

interface ICard {
  url: string;
  header: string;
  subheader: string;
  width?: number;
  round?: boolean;
}

const Print = ({ id_hiking }: { id_hiking?: number }) => {
  const [cards, setCards] = React.useState<(ICard | null)[]>([]);
  const [chevrons, setChevrons] = React.useState<ICard[]>([]);
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);

  React.useEffect(() => {
    if (!id_hiking) return;
    getHikingDataAsync(id_hiking).then(setHikingData);
  }, [id_hiking]);
  return (
    <div>
      <header className="d-print-none d-flex justify-content-center" style={{ gap: '8px' }}>
        <PohButton
          variant={ButtonVariant.Light}
          size={ButtonSize.Small}
          onClick={() => {
            const header =
              prompt('Заголовок (красным)', hikingData?.slogan || hikingData?.name) ?? '';
            const subheader = prompt('Подзаголовок (серым)', 'Походники Пензы') ?? '';
            const count = parseInt(prompt('count', '1') ?? '1');

            setCards((c) => [
              ...c,
              ...Array(count)
                .fill(1)
                .map(() => ({
                  url: logo,
                  header,
                  subheader,
                })),
            ]);
          }}
        >
          Добавить
        </PohButton>
        {hikingData && (
          <>
            <PohButton
              variant={ButtonVariant.Light}
              size={ButtonSize.Small}
              onClick={() => {
                const header = prompt('Заголовок', hikingData.name) ?? '';
                const subheader = prompt('Подзаголовок', 'Походники Пензы') ?? '';
                const count = +(prompt('Кол-во карточек', '6') ?? '1');

                setCards((c) => [
                  ...c,
                  ...Array(count)
                    .fill(1)
                    .map(() => ({
                      url: logo,
                      header,
                      subheader,
                    })),
                ]);
              }}
            >
              {hikingData.name}
            </PohButton>
            <PohButton
              variant={ButtonVariant.Light}
              size={ButtonSize.Small}
              onClick={() => {
                id_hiking &&
                  selectHikerAsync(id_hiking, { withMe: true }).then((user) => {
                    const header =
                      prompt('Имя участника', [user.name, user.surname].join(' ')) ?? '';
                    const subheader = prompt('Подзаголовок', 'Походники Пензы') ?? '';
                    const count = +(prompt('Кол-во карточек', '6') ?? '1');

                    setCards((c) => [
                      ...c,
                      ...Array(count)
                        .fill(1)
                        .map(() => ({
                          url: logo,
                          header,
                          subheader,
                        })),
                    ]);
                  });
              }}
            >
              Участник
            </PohButton>
            <PohButton
              variant={ButtonVariant.Light}
              size={ButtonSize.Small}
              onClick={() => {
                id_hiking &&
                  selectHikerAsync(id_hiking, { withMe: true }).then((user) => {
                    const header =
                      prompt('Имя участника', [user.name, user.surname].join(' ')) ?? '';
                    const subheader = prompt('Подзаголовок', 'Походники Пензы') ?? '';
                    const count = +(prompt('Кол-во карточек', '6') ?? '1');

                    setCards((c) => [
                      ...c,
                      ...Array(count)
                        .fill(1)
                        .map(() => ({
                          url: user.photo[50],
                          header,
                          subheader,
                          round: true,
                        })),
                    ]);
                  });
              }}
            >
              Участник c Фото
            </PohButton>

            <PohButton
              variant={ButtonVariant.Light}
              size={ButtonSize.Small}
              onClick={() => {
                const subheader = prompt('Верхняя дуга', hikingData.name) ?? '';
                const header = prompt('Нижняя дуга', hikingData.slogan || 'Походники Пензы') ?? '';
                const width = +(prompt('Размер (px)', '180') ?? '180');
                const count = +(prompt('Кол-во', '1') ?? '1');

                setChevrons((c) => [
                  ...c,
                  ...Array(count)
                    .fill(1)
                    .map(() => ({
                      url: hikingData.visual.photo,
                      header,
                      subheader,
                      width,
                    })),
                ]);
              }}
            >
              Шеврон похода <sup>β</sup>
            </PohButton>

            <PohButton
              variant={ButtonVariant.Light}
              size={ButtonSize.Small}
              onClick={() => {
                id_hiking &&
                  selectHikerAsync(id_hiking, { withMe: true }).then((user) => {
                    const subheader =
                      prompt('Имя участника', [user.name, user.surname].join(' ')) ?? '';
                    const header = prompt('Подзаголовок', 'Походники Пензы') ?? '';

                    const width = +(prompt('Размер (px)', '180') ?? '180');
                    const count = +(prompt('Кол-во', '1') ?? '1');

                    setChevrons((c) => [
                      ...c,
                      ...Array(count)
                        .fill(1)
                        .map(() => ({
                          url: user.photo[100],
                          header,
                          subheader,
                          width,
                        })),
                    ]);
                  });
              }}
            >
              Шеврон участника<sup>β</sup>
            </PohButton>

            <PohButton
              variant={ButtonVariant.Light}
              size={ButtonSize.Small}
              onClick={() => {
                setCards((c) => [...c, null]);
              }}
            >
              BR
            </PohButton>
          </>
        )}
      </header>
      <A4Page>
        {}
        {cards.map((card, index) =>
          !card ? (
            <br key={index} />
          ) : (
            <PohodnikCard
              key={index}
              url={card.url}
              round={!!card.round}
              subheader={card.header}
              header={card.subheader}
              onDoubleClick={() => {
                setCards((cur) => cur.filter((_, i) => i !== index));
              }}
            />
          ),
        )}
        <br />
        {chevrons.map((card, index) =>
          !card ? (
            <br key={index} />
          ) : (
            <PohodnikChevron
              key={index}
              url={card.url}
              subheader={card.header}
              header={card.subheader}
              style={{ width: card.width }}
              onDoubleClick={() => {
                setChevrons((cur) => cur.filter((_, i) => i !== index));
              }}
            />
          ),
        )}
      </A4Page>
    </div>
  );
};

export default Print;
